// Ship the canonical config schema without depending on a checkout at runtime.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { format, resolveConfig } from 'prettier';

const source = new URL('../schemas/farsight-config.schema.json', import.meta.url);
const moduleFile = fileURLToPath(new URL('../packages/graph/src/config-schema.ts', import.meta.url));
const schema = JSON.parse(readFileSync(source, 'utf8'));
const moduleText = await format(
  '// Generated by scripts/config-schema.mjs from schemas/farsight-config.schema.json.\nexport default ' +
    JSON.stringify(schema) +
    ';\n',
  { ...(await resolveConfig(moduleFile)), filepath: moduleFile },
);
if (process.argv.includes('--check')) {
  if (readFileSync(moduleFile, 'utf8') !== moduleText)
    throw new Error('Embedded config schema differs; run node scripts/config-schema.mjs');
} else {
  writeFileSync(moduleFile, moduleText);
}
